/* Scoreboard page: renders WT.board (js/scoreboard-data.js, generated by make_scoreboard.py) in the page's language. */
(function () {
  "use strict";
  const B = WT.board, es = WT.lang === "es", T = (k, en) => WT.ui(k, en);
  const $ = (s) => document.querySelector(s);
  const th = /[?&]theme=(dark|light)/.exec(location.search); if (th) document.documentElement.dataset.theme = th[1]; // dev aid, as in kit.js
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const num = (v, d = 4) => (v > 0 ? "+" : v < 0 ? "−" : "") + WT.dec(Math.abs(v).toFixed(d));
  const date = (iso) => new Date(iso + "T12:00:00Z").toLocaleDateString(WT.loc(), { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
  const V = { WIN: T("v_win", "WIN"), TIE: T("v_tie", "TIE"), LOSS: T("v_loss", "LOSS"), NA: "N/A" };
  const badge = (v) => `<span class="vd vd-${v.toLowerCase()}">${V[v] || v}</span>`;

  // static text, language switch, links that keep the language
  if (es) {
    if (WT.es.ui.sb_title) document.title = WT.es.ui.sb_title;
    document.querySelectorAll("[data-i18n]").forEach((el) => { const t = WT.es.ui[el.dataset.i18n]; if (t != null) el.innerHTML = t; });
    document.querySelectorAll("[data-i18n-aria]").forEach((el) => { const t = WT.es.ui[el.dataset.i18nAria]; if (t != null) el.setAttribute("aria-label", t); });
  }
  // links that keep the language and the EN | ES switch: js/nav.js
  if (!B) return;
  $("#sb-date").textContent = date(B.asof); $("#sb-date").setAttribute("datetime", B.asof);

  // headline tiles and a proportional strip (labels always in text, never colour alone)
  function tiles(el, d) {
    el.innerHTML = ["LOSS", "TIE", "WIN"].map((v) => `<div class="sb-tile sb-${v.toLowerCase()}"><div class="sb-n">${d[v]}</div><div class="sb-l">${V[v]}</div></div>`).join("")
      + `<div class="sb-tile sb-of"><div class="sb-n">${d.decided}</div><div class="sb-l">${T("sb_compared", "comparisons")}</div></div>`;
  }
  function strip(el, d) {
    const parts = ["LOSS", "TIE", "WIN"].filter((v) => d[v]);
    el.innerHTML = parts.map((v) => `<span class="sb-seg sb-${v.toLowerCase()}" style="flex-grow:${d[v]}" title="${V[v]}: ${d[v]}"></span>`).join("");
    el.setAttribute("aria-label", parts.map((v) => `${d[v]} ${V[v]}`).join(", ") + ` / ${d.decided}`);
  }

  // ---- 1. INCOGNITA census
  const I = B.incognita;
  tiles($("#sb-inc-tiles"), I); strip($("#sb-inc-strip"), I);
  $("#sb-inc-note").innerHTML = es
    ? `Motor de producción <code>${esc(I.engine)}</code> (<code>${esc(I.commit)}</code>), censo del ${date(I.date)}. Además, ${I.NA} comparaciones no son puntuables (N/A). De los ${I.TIE} empates: ${I.by_class.trail} por detrás, ${I.by_class.parity} a la par y ${I.by_class.underpowered} con pocos núcleos.`
    : `Production engine <code>${esc(I.engine)}</code> (<code>${esc(I.commit)}</code>), census of ${date(I.date)}. A further ${I.NA} comparisons are not scorable (N/A). Of the ${I.TIE} ties, ${I.by_class.trail} trail, ${I.by_class.parity} are at parity and ${I.by_class.underpowered} are underpowered.`;

  const GLOSS = {
    thrA1_np: ["(n,p) near threshold", "(n,p) cerca del umbral"],
    capture_FAR: ["capture, nuclei far from stability", "captura, núcleos lejos de la estabilidad"],
    fission_SELECT: ["fission, selected actinides", "fisión, actínidos seleccionados"],
    n2n_SELECT: ["(n,2n), selected nuclei", "(n,2n), núcleos seleccionados"],
    n2n_SELECT_RL3: ["(n,2n), selected nuclei, second data set", "(n,2n), núcleos seleccionados, segundo conjunto de datos"],
    np_FRESH_curated: ["(n,p), curated set", "(n,p), conjunto depurado"],
  };
  const gloss = (cell) => {
    const m = /^K\d+ Z(.+)$/.exec(cell);
    if (m) return (es ? "captura estelar (MACS), Z " : "stellar capture (MACS), Z ") + m[1].replace("-", "–");
    const g = GLOSS[cell]; return g ? g[es ? 1 : 0] : "";
  };
  const cellName = (c) => /^K\d+ /.test(c) ? "MACS " + c.split(" ")[1] : c;
  const CLS = { trail: T("cls_trail", "trail"), parity: T("cls_parity", "parity"), underpowered: T("cls_under", "underpowered") };
  const RIV = (r) => r;
  $("#sb-open").insertAdjacentHTML("beforeend",
    `<thead><tr><th scope="col">${T("th_cell", "Comparison")}</th><th scope="col">${T("th_rival", "Rival")}</th><th scope="col" class="r">${T("th_n", "Nuclei")}</th><th scope="col" class="r">${T("th_gap", "Gap")}</th><th scope="col">${T("th_ci", "95 % interval")}</th><th scope="col">${T("th_verdict", "Verdict")}</th><th scope="col">${T("th_carriers", "Largest contributors")}</th></tr></thead><tbody>`
    + I.open.map((c) => `<tr><td><code>${esc(cellName(c.cell))}</code><div class="sb-gl">${esc(gloss(c.cell))}</div></td><td>${esc(RIV(c.rival))}</td><td class="r">${c.n}</td><td class="r num">${num(c.gap)}</td><td class="num">[${num(c.lo)}, ${num(c.hi)}]</td><td>${badge(c.verdict)} <span class="sb-cls">${CLS[c.cls] || c.cls}</span></td><td class="sb-car">${c.carriers.map(esc).join(", ")}</td></tr>`).join("")
    + "</tbody>");

  const rivals = ["stock", "R_T", "CoH3", "YAHFC"].filter((r) => I.by_rival[r]);
  const sum = (o, k) => rivals.reduce((s, r) => s + o[r][k], 0);
  const rivalTable = (rows, total, hasNA) =>
    `<thead><tr><th scope="col">${T("th_rival", "Rival")}</th><th scope="col" class="r">${V.WIN}</th><th scope="col" class="r">${V.TIE}</th><th scope="col" class="r">${V.LOSS}</th>${hasNA ? `<th scope="col" class="r">N/A</th>` : ""}</tr></thead><tbody>`
    + rows.map((r) => `<tr><th scope="row">${esc(r.name)}</th><td class="r">${r.WIN}</td><td class="r">${r.TIE}</td><td class="r${r.LOSS ? " neg" : ""}">${r.LOSS}</td>${hasNA ? `<td class="r">${r.NA}</td>` : ""}</tr>`).join("")
    + `</tbody><tfoot><tr><th scope="row">${T("total", "All")}</th><td class="r">${total.WIN}</td><td class="r">${total.TIE}</td><td class="r">${total.LOSS}</td>${hasNA ? `<td class="r">${total.NA}</td>` : ""}</tr></tfoot>`;
  $("#sb-rival").insertAdjacentHTML("beforeend", rivalTable(rivals.map((r) => Object.assign({ name: r }, I.by_rival[r])), { WIN: sum(I.by_rival, "WIN"), TIE: sum(I.by_rival, "TIE"), LOSS: sum(I.by_rival, "LOSS"), NA: sum(I.by_rival, "NA") }, true));

  $("#sb-changes").innerHTML = I.changes.map((c) => `<li><code>${esc(c.cell)}</code> ${T("vs", "vs")} ${esc(c.rival)}: ${badge(c.from)} → ${badge(c.to)} <span class="num">${num(c.gap)} [${num(c.lo)}, ${num(c.hi)}]</span></li>`).join("");

  // ---- 2. TERRA board
  const R = B.terra;
  tiles($("#sb-terra-tiles"), R); strip($("#sb-terra-strip"), R);
  $("#sb-terra-note").innerHTML = es
    ? `Candidato <code>${R.product}</code>, tablero del ${date(R.date)}; incluye ${R.loso.WIN + R.loso.TIE + R.loso.LOSS} comparaciones dejando una serie fuera (${R.loso.WIN} ${V.WIN}, ${R.loso.TIE} ${V.TIE}, ${R.loso.LOSS} ${V.LOSS}).`
    : `Candidate <code>${R.product}</code>, board of ${date(R.date)}; includes ${R.loso.WIN + R.loso.TIE + R.loso.LOSS} leave-one-series-out comparisons (${R.loso.WIN} ${V.WIN}, ${R.loso.TIE} ${V.TIE}, ${R.loso.LOSS} ${V.LOSS}).`;
  const L = R.losses[0];
  if (L) $("#sb-terra-loss").innerHTML = es
    ? `Cobertura de la incertidumbre en (n,p) (<code>${esc(L.cell)}</code>) frente a ${esc(L.rival)}: ${num(L.gap, 3)} [${num(L.lo, 3)}, ${num(L.hi, 3)}]. Las bandas (n,p) de TERRA se ensancharon a propósito para que fueran honestas, y ahora cubren de más los datos con los que se ajustaron; ese ensanchamiento cambió una victoria por esta derrota y dos victorias por empates, a cambio de seis victorias al dejar una serie fuera.`
    : `Uncertainty coverage in (n,p) (<code>${esc(L.cell)}</code>) against ${esc(L.rival)}: ${num(L.gap, 3)} [${num(L.lo, 3)}, ${num(L.hi, 3)}]. TERRA's (n,p) bands were deliberately widened to be honest, and they now over-cover the data they were fitted on; that widening turned one win into this loss and two wins into ties, and gained six wins in the leave-one-series-out view.`;
  $("#sb-trival").insertAdjacentHTML("beforeend", rivalTable(R.by_rival.map((r) => Object.assign({ name: r.rival }, r)), R, false));

  $("#sb-src").innerHTML = es
    ? `Fuente: el registro de investigación del proyecto (censo ${esc(I.census || "LEDGERSYNC")} del ${date(I.date)}; tablero GOAL-ALL-METRICS R072w del ${date(R.date)}). Los números se generan con <code>make_scoreboard.py</code>.`
    : `Source: the project's research ledger (${esc(I.census || "LEDGERSYNC")} census of ${date(I.date)}; GOAL-ALL-METRICS board R072w of ${date(R.date)}). Numbers are generated by <code>make_scoreboard.py</code>.`;
  // ---------- hero: one glowing dot per comparison, engine above, TERRA below; counts tick up as the dots arrive ----------
  (function hero() {
    const cv = $("#sb-hero-cv"); if (!cv) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const css = getComputedStyle(document.documentElement), col = { WIN: css.getPropertyValue("--win-ink").trim() || "#3fd3a8", TIE: "#9aa6bf", LOSS: css.getPropertyValue("--loss-ink").trim() || "#ff8b80", NA: "#3a4560" };
    const rows = [[I, T("sb_h_eng", "The engine against other codes")], [B.terra, T("sb_h_terra", "The data product against evaluated libraries")]].filter((r) => r[0]);
    const lists = rows.map(([b]) => [].concat(Array(b.WIN || 0).fill("WIN"), Array(b.TIE || 0).fill("TIE"), Array(b.LOSS || 0).fill("LOSS")));
    let t0 = 0, W = 0, H = 0, dpr = 1;
    function size() { dpr = Math.min(2, window.devicePixelRatio || 1); const ps = getComputedStyle(cv.parentElement); W = Math.floor(cv.parentElement.clientWidth - parseFloat(ps.paddingLeft) - parseFloat(ps.paddingRight)); H = W < 640 ? 2 * 250 : Math.round(Math.min(420, Math.max(300, W * 0.36))); cv.style.width = W + "px"; cv.style.height = H + "px"; cv.width = W * dpr; cv.height = H * dpr; }
    function frame(now) {
      if (!t0) t0 = now; const u = reduce ? 1 : Math.min(1, (now - t0) / 2200);
      const g = cv.getContext("2d"); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, W, H);
      const bandH = H / rows.length;
      rows.forEach(([b, label], ri) => {
        const L = lists[ri], y0 = ri * bandH, n = L.length, narrow = W < 640, labW = narrow ? 0 : Math.min(330, W * 0.36), top = narrow ? 104 : 22, area = W - labW - 10;
        const cols = Math.max(1, Math.ceil(Math.sqrt(n * area / (bandH - top - 12)))), cell = Math.min(22, area / cols, (bandH - top - 12) / Math.ceil(n / cols)), r = cell * 0.36;
        const shown = Math.floor(n * u), cnt = { WIN: 0, TIE: 0, LOSS: 0 };
        for (let i = 0; i < shown; i++) cnt[L[i]]++;
        // label and ticking counts
        g.fillStyle = "rgba(220,228,248,.75)"; g.font = "600 13px 'IBM Plex Sans', sans-serif"; g.textBaseline = "top"; g.fillText(label, 0, y0 + 8);
        let x = 0; g.textBaseline = "alphabetic";
        for (const k of ["WIN", "TIE", "LOSS"]) { g.font = "600 34px 'IBM Plex Sans', sans-serif"; g.fillStyle = col[k]; const s = String(cnt[k]); g.fillText(s, x, y0 + 68); const w = g.measureText(s).width; g.font = "600 12px 'IBM Plex Sans', sans-serif"; g.fillStyle = "rgba(220,228,248,.7)"; g.fillText(V[k], x, y0 + 86); x += Math.max(w, g.measureText(V[k]).width) + 22; }
        // the dots
        for (let i = 0; i < shown; i++) {
          const k = L[i], cx = labW + 10 + (i % cols + 0.5) * cell, cy = y0 + top + (Math.floor(i / cols) + 0.5) * cell;
          const pulse = k === "LOSS" ? 1 + 0.35 * Math.sin(now / 260) : 1, born = Math.min(1, (n * u - i) / 3);
          g.globalCompositeOperation = "lighter"; g.globalAlpha = 0.35 * born; g.fillStyle = col[k]; g.beginPath(); g.arc(cx, cy, r * 2.1 * pulse, 0, Math.PI * 2); g.fill();
          g.globalCompositeOperation = "source-over"; g.globalAlpha = born; g.beginPath(); g.arc(cx, cy, r * (k === "LOSS" ? pulse : 1), 0, Math.PI * 2); g.fill();
        }
        g.globalAlpha = 1;
      });
      if (!reduce) requestAnimationFrame(frame);
    }
    size(); window.addEventListener("resize", () => { size(); if (reduce) requestAnimationFrame(frame); }); requestAnimationFrame(frame); if (reduce) window.addEventListener("load", () => requestAnimationFrame(frame));
    cv.setAttribute("role", "img");
    cv.setAttribute("aria-label", rows.map(([b, l]) => `${l}: ${b.WIN || 0} ${V.WIN}, ${b.TIE || 0} ${V.TIE}, ${b.LOSS || 0} ${V.LOSS}`).join(". "));
  })();
})();
